breaking_changes.Adaptation_method:
Replace direct internal imports with named imports from the main Redux entry point. For example:
Before: import createStore from 'redux/lib/createStore';
After: import { createStore } from 'redux';

Ensure that store.getState(), store.subscribe(), or store.unsubscribe() are not called during a dispatch cycle, such as inside a reducer or middleware. Move such calls to safe execution contexts. For example:

Before:
function reducer(state, action) {
  if (action.type === 'SOME_ACTION') {
    const currentState = store.getState(); // Throws error
  }
  return state;
}

After:
// Use the state passed as an argument to the reducer
function reducer(state, action) {
  if (action.type === 'SOME_ACTION') {
    // Use `state` directly instead of calling getState()
    console.log(state);
  }
  return state;
}

// For subscriptions, register listeners outside reducers, e.g., in components:
componentDidMount() {
  this.unsubscribe = store.subscribe(() => {
    console.log(store.getState()); // Safe to call in callback
  });
}

componentWillUnmount() {
  // Unsubscribe outside of dispatch context
  if (this.unsubscribe) this.unsubscribe();
}
